function json(args) { return JSON.parse(execFileSync(process.execPath, args, { encoding: "utf8" })); }
function assertFails(args, expression) { const result = spawnSync(process.execPath, args, { encoding: "utf8" }); assert.notEqual(result.status, 0); assert.match(result.stderr, expression); }
function hash(value) { return createHash("sha256").update(value).digest("hex"); }
